head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50002";
scwin.dataDiv = "";

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — isMaindoc

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_isMaindoc", fn: function(){ return ((dma_pageContext.get("isMaindoc") ?? "")); } }, { id: "tr_61", fn: function(){ return ((dma_pageContext.get("isMaindoc") ?? "")); } }, { id: "tr_69", fn: function(){ return ((dma_pageContext.get("isMaindoc") ?? "")); } }, { id: "tr_71", fn: function(){ return ((dma_pageContext.get("isMaindoc") ?? "")); } }, { id: "tr_79", fn: function(){ return ((dma_pageContext.get("isMaindoc") ?? "")); } }, { id: "tr_81", fn: function(){ return ((dma_pageContext.get("isMaindoc") ?? "")); } }, { id: "tr_89", fn: function(){ return ((dma_pageContext.get("isMaindoc") ?? "")); } }, { id: "if_isMaindoc_2", fn: function(){ return ((dma_pageContext.get("isMaindoc") ?? "")); } }, { id: "tr_102", fn: function(){ return ((dma_pageContext.get("isMaindoc") ?? "")); } }, { id: "tr_110", fn: function(){ return ((dma_pageContext.get("isMaindoc") ?? "")); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_formCd", fn: function () { return String((dma_pageContext.get("formCd") ?? "")); } },
        { childId: "ipt_formVer", fn: function () { return String((dma_pageContext.get("formVer") ?? "")); } },
        { childId: "ipt_ldMktTpCd", fn: function () { return String((dma_pageContext.get("ldMktTpCd") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_viewForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50002.onpageload' });
    }
};

